testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarIndice, buscarPorIndice } from './solution.mjs';

const consultas = [
  { id: 1, paciente_id: 2, dia: '2026-08-27', hora: '10:00' },
  { id: 2, paciente_id: 2, dia: '2026-08-28', hora: '09:00' },
  { id: 3, paciente_id: 7, dia: '2026-08-27', hora: '10:00' },
];

test('índice de uma coluna devolve as linhas do valor, na ordem original', () => {
  const porPaciente = criarIndice(consultas, ['paciente_id']);
  const achadas = buscarPorIndice(porPaciente, [2]);
  assert.equal(achadas.length, 2);
  assert.equal(achadas[0].id, 1);
  assert.equal(achadas[1].id, 2);
});

test('chave que não existe devolve lista vazia', () => {
  const porPaciente = criarIndice(consultas, ['paciente_id']);
  assert.deepEqual(buscarPorIndice(porPaciente, [99]), []);
});

test('índice composto junta os valores com | e precisa da ordem certa', () => {
  const porDiaHora = criarIndice(consultas, ['dia', 'hora']);
  const daTarde = buscarPorIndice(porDiaHora, ['2026-08-27', '10:00']);
  assert.equal(daTarde.length, 2);
  assert.deepEqual(daTarde.map((c) => c.id), [1, 3]);
  // com os valores na ordem trocada, a chave é outra — não acha nada
  assert.deepEqual(buscarPorIndice(porDiaHora, ['10:00', '2026-08-27']), []);
});

test('lista vazia de linhas gera um fichário vazio', () => {
  const indice = criarIndice([], ['paciente_id']);
  assert.deepEqual(buscarPorIndice(indice, [1]), []);
});

solutionCode:
// Simulação de índice: um objeto que mapeia a chave (valor ou combinação
// de valores, virados texto e juntados com |) para a lista de linhas.
export function criarIndice(linhas, colunas) {
  const indice = {};
  for (const linha of linhas) {
    const chave = colunas.map((coluna) => String(linha[coluna])).join('|');
    if (indice[chave] === undefined) {
      indice[chave] = [];
    }
    indice[chave].push(linha);
  }
  return indice;
}

// Consulta o "fichário": mesma chave de criarIndice, mas com os VALORES.
export function buscarPorIndice(indice, valores) {
  const chave = valores.map((valor) => String(valor)).join('|');
  return indice[chave] ?? [];
}
